"""Independent manual debugger goldens (not generated by Rust)."""
import io
import sys
import unittest
from dataclasses import replace
from statelessness import (Artifact, AuditTrace, Check, Metadata, RunConfig,
    TraceStep, TraceV2, StepEvidence, Transition, ModelError)
from statelessness.debugger import EvidenceViewer, InputPolicy, VerificationLimits
from statelessness.search import ShrinkLimits


class Counter:
    def __init__(self): self.calls = 0
    def metadata(self): return Metadata('debug-counter')
    def initial_state(self): return 0
    def decode_state(self, value): self.calls += 1; return int(value)
    def decode_input(self, value): return int(value)
    def encode_state_into(self, value, out): out.append(str(value).encode())
    def encode_input_into(self, value, out): out.append(str(value).encode())
    def encode_output_into(self, value, out): out.append(str(value).encode())
    def step(self, state, input): self.calls += 1; return Transition(state + input)
    def check_state(self, state): return (Check('ceiling', 'failed' if state >= 6 else 'passed'),)
    def check_transition(self, *args): return ()
    def is_enabled(self, state, input): return input > 0
    def simpler_inputs(self, input): return range(1, input)


def fixture():
    # The original run checkpoint is four, not Counter.initial_state() == zero.
    return AuditTrace(Metadata('debug-counter'), RunConfig(), b'4', (Check('ceiling'),),
        (TraceStep(b'1', Transition(0).disposition, (), b'5', (Check('ceiling'),)),
         TraceStep(b'1', Transition(0).disposition, (), b'6', (Check('ceiling', 'failed'),))), 'property_failed')


class DebuggerTests(unittest.TestCase):
    def test_passive_boundary_and_full_width_checkpoint(self):
        trace = fixture()
        value = TraceV2(trace, (1 << 64) - 3, steps=(StepEvidence((1 << 64) - 2, 1), StepEvidence((1 << 64) - 1, 1)))
        model = Counter()
        view = EvidenceViewer(Artifact(value))
        self.assertEqual(model.calls, 0)
        self.assertEqual(view.retained_range, ((1 << 64) - 3, (1 << 64) - 1))
        self.assertEqual(view.boundary(0).before, b'4')
        self.assertEqual(view.boundary(2).before, b'5')
        self.assertEqual(view.failure(2, 0).phase, 'state')
        self.assertEqual(view.preview(2, 0).total_bytes, 1)
        self.assertFalse(view.preview(2, 0).complete)
        self.assertIsNone(view.boundary(3))
        with self.assertRaises(ModelError): view.failure(1, 0)
        self.assertEqual(view.verify(model).outcome, 'exact')

    def test_legacy_phase_and_semantic_validation(self):
        view = EvidenceViewer(Artifact(fixture()))
        with self.assertRaisesRegex(ModelError, 'phase unknown'): view.failure(2, 0)
        with self.assertRaises(ModelError):
            EvidenceViewer(Artifact(replace(fixture(), termination='completed')))
        result = view.minimize(Counter(), 2, 0, phase='state', limits=ShrinkLimits(max_replayed_transitions=30))
        self.assertTrue(result.validated_original)
        self.assertEqual(result.minimized.inputs, (1, 1))
        self.assertGreaterEqual(result.replayed_transitions, 4)

    def test_phase_spoof_and_budget_reject_before_execution(self):
        evidence = TraceV2(fixture(), steps=(StepEvidence(1, 1), StepEvidence(2, 0)))
        view, model = EvidenceViewer(Artifact(evidence)), Counter()
        with self.assertRaisesRegex(ModelError, 'budget'): view.minimize(model, 2, 0, limits=ShrinkLimits(max_replayed_transitions=1))
        self.assertEqual(model.calls, 0)
        with self.assertRaisesRegex(ModelError, 'phase differs'): view.minimize(model, 2, 0)

    def test_policy_is_not_fabricated(self):
        trace = replace(fixture(), config=RunConfig(parameters=(('stateless.debug.environment', 'positive'), ('stateless.debug.origin', 'simulation'))))
        view, model = EvidenceViewer(Artifact(trace)), Counter()
        with self.assertRaisesRegex(ModelError, 'explicit policy'): view.minimize(model, 2, 0, phase='state')
        self.assertEqual(model.calls, 0)
        with self.assertRaisesRegex(ModelError, 'differs'): view.minimize(model, 2, 0, phase='state', policy=InputPolicy('other', lambda *args: True))
        result = view.minimize(model, 2, 0, phase='state', policy=InputPolicy('positive', lambda m, s, i: i == 1))
        self.assertEqual(result.minimized.inputs, (1, 1))

    def test_roundtrip_passive_read(self):
        from statelessness.trace_binary import audit_to_bytes
        view = EvidenceViewer.read(io.BytesIO(audit_to_bytes(fixture())))
        self.assertEqual(view.boundary(2).after, b'6')

    def test_explicit_verification_limits(self):
        view, model = EvidenceViewer(Artifact(fixture())), Counter()
        with self.assertRaisesRegex(ModelError, 'transition budget'):
            view.verify(model, limits=VerificationLimits(1))
        self.assertEqual(model.calls, 0)

    def test_v2_three_pass_accounting(self):
        value = TraceV2(fixture(), steps=(StepEvidence(1, 1), StepEvidence(2, 1)))
        view, model = EvidenceViewer(Artifact(value)), Counter()
        with self.assertRaisesRegex(ModelError, 'original validation'):
            view.minimize(model, 2, 0, limits=ShrinkLimits(max_replayed_transitions=4))
        # Phase pass has executed; workbench replay and shrink have not.
        self.assertEqual(model.calls, 3)
        result = view.minimize(Counter(), 2, 0, limits=ShrinkLimits(max_replayed_transitions=6))
        self.assertTrue(result.validated_original)
        self.assertEqual(result.replayed_transitions, 6)

    def test_legacy_rust_u64_checkpoint_syntax(self):
        trace=replace(fixture(),steps=(),termination='completed',config=RunConfig(parameters=(('stateless.monitor.checkpoint_after_sequence','+018446744073709551615'),)))
        self.assertEqual(EvidenceViewer(Artifact(trace)).retained_range,((1<<64)-1,(1<<64)-1))
